package chtypes

// setup_cases_test.go — the process setup's shared public-API cases
// (tests/fixtures/abi-v2/setup-cases.json, generated by
// scripts/abi-v1/emit/setup_cases.py and read by all four bindings), run
// through the public API over a fresh copy of a stub library. Without
// CHTYPES_ABI2_STUBS it skips LOUDLY by name.

import (
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

type setupCaseExpect struct {
	OK     bool    `json:"ok"`
	Class  string  `json:"class"`
	Status string  `json:"status"`
	ChCode *int32  `json:"ch_code"`
	ChName *string `json:"ch_name"`
	Reason string  `json:"reason"`
	// Message, on an error the library answered, is the message it must
	// carry, byte for byte.
	Message *string `json:"message"`
	// ImageZone, on a successful open, is the zone the image was set up
	// with, read back with the document's image_zone_probe.
	ImageZone *string `json:"image_zone"`
}

// declinedExpect is one entry a describe step must decode from the schema
// description's filter_declined_settings: the name's bytes as hex, the tier's
// and the layer's raw spellings, and whether the description lists each (rule
// r3).
type declinedExpect struct {
	NameHex    string `json:"name_hex"`
	Tier       string `json:"tier"`
	TierKnown  bool   `json:"tier_known"`
	Layer      string `json:"layer"`
	LayerKnown bool   `json:"layer_known"`
}

type setupCaseStep struct {
	Op       string          `json:"op"`
	Timezone string          `json:"timezone"`
	Variant  string          `json:"variant"`
	Request  string          `json:"request"`
	Allow    *bool           `json:"allow"`
	Expect   setupCaseExpect `json:"expect"`
	// The server ops (rule r7): a name a later step uses, the statement to
	// compile, the named server it compiles on (none when empty), the named
	// schema to close, and the live-handle counts to require.
	As        string         `json:"as"`
	Server    string         `json:"server"`
	Schema    string         `json:"schema"`
	Statement string         `json:"statement"`
	Live      map[string]int `json:"live"`
	// The filter ops (rule r7): the named schema and filter, the expression,
	// the body (CSV), and the rows_passed a batch result must report.
	Filter     string `json:"filter"`
	Expression string `json:"expression"`
	Body       string `json:"body"`
	RowsPassed *int   `json:"rows_passed"`
	// The describe op: the filter_declined_settings the named schema's
	// description must decode to, in order, when the describe succeeds.
	Declined []declinedExpect `json:"declined"`
}

type setupCasesDoc struct {
	ImageZoneProbe string      `json:"image_zone_probe"`
	Cases          []setupCase `json:"cases"`
}

type setupCase struct {
	ID      string          `json:"id"`
	Variant string          `json:"variant"`
	Steps   []setupCaseStep `json:"steps"`
	// NotExpressible names the bindings that cannot express the case, and why.
	NotExpressible map[string]string `json:"not_expressible"`
}

func loadSetupCases(t *testing.T) setupCasesDoc {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller(0) failed")
	}
	path := filepath.Join(filepath.Dir(file), "..", "..", "tests", "fixtures", "abi-v2", "setup-cases.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var doc setupCasesDoc
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	if len(doc.Cases) == 0 {
		t.Fatalf("%s: zero cases; a suite that ran nothing must not pass", path)
	}
	if doc.ImageZoneProbe == "" {
		t.Fatalf("%s: no image_zone_probe", path)
	}
	return doc
}

// setupStepOutcome compares one step's outcome with its expectation, and
// returns what differs, or "" when they agree.
func setupStepOutcome(want setupCaseExpect, err error) string {
	if want.OK {
		if err != nil {
			return fmt.Sprintf("want success, got %T: %v", err, err)
		}
		return ""
	}
	if err == nil {
		return fmt.Sprintf("want a %s error, got success", want.Class)
	}
	switch want.Class {
	case "artifact_incompatible", "artifact_corrupt":
		sentinel := ErrArtifactIncompatible
		if want.Class == "artifact_corrupt" {
			sentinel = ErrArtifactCorrupt
		}
		var ae *ArtifactError
		if !errors.Is(err, sentinel) || !errors.As(err, &ae) {
			return fmt.Sprintf("want a %s error, got %T: %v", want.Class, err, err)
		}
		if want.Reason != "" && ae.Reason != want.Reason {
			return fmt.Sprintf("reason %q, want %q", ae.Reason, want.Reason)
		}
		return ""
	}
	var matched bool
	switch want.Class {
	case "schema":
		var e *SchemaError
		matched = errors.As(err, &e)
	case "unsupported":
		var e *UnsupportedError
		matched = errors.As(err, &e)
	case "usage":
		var e *UsageError
		matched = errors.As(err, &e)
	case "internal":
		var e *InternalError
		matched = errors.As(err, &e)
	default:
		return fmt.Sprintf("the case names an error class this runner does not know: %q", want.Class)
	}
	if !matched {
		return fmt.Sprintf("want a %s error, got %T: %v", want.Class, err, err)
	}
	if want.Status == "" && want.ChCode == nil && want.ChName == nil {
		return "" // a binding's own usage error, raised before any call, carries no call fields
	}
	ce, ok := AsCallError(err)
	if !ok {
		return fmt.Sprintf("%T carries no call error fields", err)
	}
	if want.Status != "" && ce.Status.String() != want.Status {
		return fmt.Sprintf("status %s, want %s", ce.Status, want.Status)
	}
	if want.ChCode != nil && ce.ChCode != *want.ChCode {
		return fmt.Sprintf("ch_code %d, want %d", ce.ChCode, *want.ChCode)
	}
	if want.ChName != nil && ce.ChName != *want.ChName {
		return fmt.Sprintf("ch_name %q, want %q", ce.ChName, *want.ChName)
	}
	if want.Message != nil && ce.Message != *want.Message {
		return fmt.Sprintf("message %q, want %q", ce.Message, *want.Message)
	}
	return ""
}

// declinedOutcome compares a description's filter_declined_settings with a
// describe step's expectation, and returns what differs, or "".
func declinedOutcome(d SchemaDescription, want []declinedExpect) string {
	got := d.FilterDeclinedSettings
	if len(got) != len(want) {
		return fmt.Sprintf("filter_declined_settings has %d entries, want %d: %+v", len(got), len(want), got)
	}
	for i, w := range want {
		if hex.EncodeToString([]byte(got[i].Name)) != w.NameHex {
			return fmt.Sprintf("entry %d: name %q, want hex %s", i, got[i].Name, w.NameHex)
		}
		if string(got[i].Tier) != w.Tier || got[i].Tier.Known() != w.TierKnown {
			return fmt.Sprintf("entry %d: tier %q (known %v), want %q (known %v)", i, got[i].Tier, got[i].Tier.Known(), w.Tier, w.TierKnown)
		}
		if string(got[i].Layer) != w.Layer || got[i].Layer.Known() != w.LayerKnown {
			return fmt.Sprintf("entry %d: layer %q (known %v), want %q (known %v)", i, got[i].Layer, got[i].Layer.Known(), w.Layer, w.LayerKnown)
		}
	}
	return ""
}

// TestSetupCases runs every shared setup case: one fresh image per variant the
// case opens, no setup recorded at its start, and each step through the public
// API.
func TestSetupCases(t *testing.T) {
	stubDir(t) // skips loudly without the stubs
	doc := loadSetupCases(t)
	for _, c := range doc.Cases {
		t.Run(c.ID, func(t *testing.T) {
			if why, skip := c.NotExpressible["go"]; skip {
				t.Skipf("not expressible in Go: %s", why)
			}
			resetSetup(t)
			t.Setenv("CHTYPES_ALLOW_UNVERIFIED_LIBRARY", "1")
			images := map[string]string{}
			image := func(variant string) string {
				if variant == "" {
					variant = c.Variant
				}
				if images[variant] == "" {
					images[variant] = stubFile(t, variant)
				}
				return images[variant]
			}
			if len(c.Steps) == 0 {
				t.Fatal("a case with no steps")
			}
			// The case's open library, and the servers and schemas its server
			// ops (rule r7) name.
			var current *Library
			servers := map[string]*Server{}
			schemas := map[string]*Schema{}
			filters := map[string]*Filter{}
			var rowsPassed *uint64
			var described *SchemaDescription
			for i, s := range c.Steps {
				var err error
				var lib *Library
				switch {
				case s.Op == "server_close":
					if err := servers[s.Server].Close(); err != nil {
						t.Fatalf("step %d: closing server %q: %v", i, s.Server, err)
					}
					continue
				case s.Op == "schema_close":
					if err := schemas[s.Schema].Close(); err != nil {
						t.Fatalf("step %d: closing schema %q: %v", i, s.Schema, err)
					}
					continue
				case s.Op == "filter_close":
					if err := filters[s.Filter].Close(); err != nil {
						t.Fatalf("step %d: closing filter %q: %v", i, s.Filter, err)
					}
					continue
				case s.Op == "describe":
					var d SchemaDescription
					d, err = schemas[s.Schema].Describe()
					described = nil
					if err == nil {
						described = &d
					}
				case s.Op == "filter_new":
					var f *Filter
					f, err = schemas[s.Schema].CompileFilter(s.Expression)
					filters[s.As] = f
				case s.Op == "rows":
					var opts []RowsOption
					if s.Filter != "" {
						opts = append(opts, WithRowFilter(filters[s.Filter]))
					}
					var res BatchResult
					res, err = schemas[s.Schema].Rows(CSV, []byte(s.Body), opts...)
					rowsPassed = nil
					if err == nil {
						rowsPassed = &res.RowsPassed
					}
				case s.Op == "live":
					// The stub's own live-handle counts, not a value the case
					// sets by hand.
					got, lerr := current.LiveHandles()
					if lerr != nil {
						t.Fatalf("step %d: live_handles: %v", i, lerr)
					}
					for kind, want := range s.Live {
						if got[kind] != uint64(want) {
							t.Fatalf("step %d: live %s = %d, want %d (%v)", i, kind, got[kind], want, got)
						}
					}
					continue
				case s.Op == "server_new":
					var srv *Server
					srv, err = current.NewServer(ServerProfile{Timezone: "UTC"})
					servers[s.As] = srv
				case s.Op == "compile":
					var opts []CompileOption
					if s.Server != "" {
						opts = append(opts, OnServer(servers[s.Server]))
					}
					var schema *Schema
					schema, err = current.CompileTable(s.Statement, opts...)
					if s.As != "" {
						schemas[s.As] = schema
					}
				case s.Op == "setup":
					err = Setup(SetupOptions{Timezone: s.Timezone})
				case s.Op == "open" && s.Request != "":
					// A registry over an empty cache, offline, autofetch off.
					var reg *Registry
					reg, err = NewRegistry(WithFetchOptions(FetchOptions{
						CacheDir: t.TempDir(), SystemDirs: []string{t.TempDir()}, Offline: true,
					}), WithAutoFetch(false))
					if err != nil {
						t.Fatalf("step %d: constructing a registry: %v", i, err)
					}
					lib, err = reg.For(s.Request)
				case s.Op == "open":
					lib, err = OpenUnverified(image(s.Variant), s.Allow == nil || *s.Allow)
				default:
					t.Fatalf("step %d: an op this runner does not know: %q", i, s.Op)
				}
				if lib != nil {
					current = lib
				}
				diff := setupStepOutcome(s.Expect, err)
				if diff == "" && s.Op == "describe" && s.Expect.OK {
					// The list as this binding decoded it from the document the
					// stub answered, never a value the case sets by hand. A
					// describe the case expects to fail has no list.
					diff = declinedOutcome(*described, s.Declined)
				}
				if diff == "" && s.RowsPassed != nil && (rowsPassed == nil || *rowsPassed != uint64(*s.RowsPassed)) {
					diff = fmt.Sprintf("rows_passed differs from %d (or the call failed): the stub says whether the filter reached the library", *s.RowsPassed)
				}
				if diff == "" && s.Expect.ImageZone != nil {
					zone, perr := lib.ValidateType(doc.ImageZoneProbe)
					switch {
					case perr != nil:
						diff = fmt.Sprintf("reading the image zone back: %v", perr)
					case zone != *s.Expect.ImageZone:
						diff = fmt.Sprintf("the image was set up with zone %q, want %q", zone, *s.Expect.ImageZone)
					}
				}
				if diff != "" {
					t.Fatalf("step %d (%s %q %s%s): %s", i, s.Op, s.Timezone, s.Variant, s.Request, diff)
				}
			}
		})
	}
}
